"use strict";

// The Family C positive control, in the same package as the ambiguous
// modules beside it -- and carrying a destructuring statement of the very
// shape RWF-025 stops recording, so that removing those marks is shown NOT
// to disturb a module whose export really is attributable.
//
// Its whole-module export is a single UNCONDITIONAL top-level assignment
// with no throwing call (or abrupt completion) anywhere above it, so its
// identity is a fact: `neverCalled` IS this module's exported value. The
// control entrypoint requires this module and never calls it, so the
// target is genuinely unreachable and NOT_AFFECTED here is a real proof.
function neverCalled(input) {
  return "stable:" + input;
}

// A private helper, deliberately NOT the exported name: the computed key
// below names `helper`, so this file exercises the RWF-025 shape without
// entangling it with the SEPARATE, still-open twin defect in
// commonjs-reexports.ts's own `markAssigned` (see FINDINGS.md's RWF-025
// entry), which would refuse to bind an exported name that appears
// anywhere under an assignment target.
function helper() {
  return "helper";
}

function keyFor(fn) {
  return "handler:" + fn.name;
}

const REGISTRY = { "handler:helper": "registered" };
let seen;

({ [keyFor(helper)]: seen } = REGISTRY);
void seen;

module.exports = neverCalled;
